function Test-BackupAge {
    param(
        [string]$SqlInstance,
        [int]$MaxHoursOld = 24
    )
    $query = "SELECT d.name AS DatabaseName,
        MAX(b.backup_finish_date) AS LastBackup
        FROM sys.databases d
        LEFT JOIN msdb.dbo.backupset b
               ON d.name = b.database_name
        WHERE d.database_id > 4 GROUP BY d.name"
    $results = Invoke-DbaQuery -SqlInstance $SqlInstance -Query $query
    foreach ($row in $results) {
        if ($null -eq $row.LastBackup) {
            Write-Host "$SqlInstance / $($row.DatabaseName): NEVER BACKED UP"
            continue
        }
        $hoursOld = ((Get-Date) - $row.LastBackup).TotalHours
        if ($hoursOld -gt $MaxHoursOld) {
            Write-Host "$SqlInstance / $($row.DatabaseName): OVERDUE"
        } else {
            Write-Host "$SqlInstance / $($row.DatabaseName): OK"
        }
    }
}
